{
  "IP": "neorv32_trng",
  "Conceptual Assets": [
    {
      "Concept ID": "C1",
      "Concept Name": "Generated random data",
      "Unit": "neorv32_trng",
      "Information": "The IP generates random bytes that software reads from the random-data register; the bytes are produced in the internal sampling register and returned through the bus response.",
      "Rubric": {
        "Confidentiality": "yes",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "The random word can be exposed by the bus readback at line 117. The word is formed in sample_sreg at line 360 and carried through the generator and FIFO paths at lines 139 and 161, so corruption of those elements can change the returned value. The enable and FIFO-clear paths can stop generation or discard buffered words at lines 137 and 170, preventing the required read at lines 114-117.",
      "Objectives At Risk": [
        "C",
        "I",
        "A"
      ],
      "Attack": "An attacker could read the bus data, tamper with the generator or FIFO data path to obtain or alter random words, or disable and clear the pool to prevent delivery.",
      "Enters Through": [],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [],
      "Held Lines": [
        360
      ],
      "Exit Lines": [
        117
      ]
    },
    {
      "Concept ID": "C2",
      "Concept Name": "TRNG enable setting",
      "Unit": "neorv32_trng",
      "Information": "This setting controls whether the random generator operates and whether the random FIFO is cleared; the IP depends on it to produce and retain random data.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "A bus write changes the stored enable setting at line 105 without an integrity check. The setting reaches the generator at line 137 and also causes FIFO clearing when low at line 170, so changing it can stop random-data production and delivery.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An unauthorized bus write could clear the enable bit, disable entropy generation, and prevent subsequent random data from being returned.",
      "Enters Through": [
        "bus_req_i.data"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        105
      ],
      "Held Lines": [
        105
      ],
      "Exit Lines": [
        109
      ]
    },
    {
      "Concept ID": "C3",
      "Concept Name": "FIFO-clear command",
      "Unit": "neorv32_trng",
      "Information": "This bus-written command clears buffered random bytes; the IP uses it to discard the current random-data pool.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "A bus write sets fifo_clr at line 106 without an integrity check, allowing the clear command to be changed. The command drives the FIFO clear condition at line 170 and the FIFO clear input at line 157, so it can discard required random data and block its delivery.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An unauthorized bus write could assert the clear command and discard buffered entropy before a consumer can read it.",
      "Enters Through": [
        "bus_req_i.data"
      ],
      "Leaves Through": [],
      "Entry Lines": [
        106
      ],
      "Held Lines": [
        106
      ],
      "Exit Lines": []
    },
    {
      "Concept ID": "C4",
      "Concept Name": "Random-data availability status",
      "Unit": "neorv32_trng",
      "Information": "This status indicates whether the random FIFO contains a byte and controls whether a bus read returns that byte or zeros; it is generated by the FIFO instance and reported in the control readback.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "The FIFO instance's avail_o status is the source at line 167, and corruption of that black-box status or its write, read, and clear controls at lines 157, 162, and 165 can make the reported availability incorrect. The status gates the returned value at line 114, selecting zero at line 115 instead of random data at line 117, so it can withhold the required transfer.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could manipulate FIFO clearing or reads, or tamper with the FIFO status, to make the pool appear empty and suppress random-data responses.",
      "Enters Through": [],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [],
      "Held Lines": [
        167
      ],
      "Exit Lines": [
        112
      ]
    }
  ],
  "Not Kept": [
    {
      "Candidate Name": "Bus request and response transaction",
      "Candidate Unit": "neorv32_trng",
      "Merged Into": "",
      "Why Not Kept": "The bus transaction is only forwarded or used to access the enable, clear command, status, and random-data response, so forwarded transactions and transfer records do not make it a separate asset."
    },
    {
      "Candidate Name": "FIFO transfer strobes and buffering state",
      "Candidate Unit": "neorv32_trng",
      "Merged Into": "",
      "Why Not Kept": "fifo.we, fifo.re, fifo.free, and fifo.half only time or report movement of generated random data and are excluded as buffering or pacing information; fifo.avail is kept separately as the generated-data availability exception."
    },
    {
      "Candidate Name": "Generator sequencing and debiasing state",
      "Candidate Unit": "neorv32_trng",
      "Merged Into": "",
      "Why Not Kept": "The sample counter, debias state, debias register, and intermediate values only sequence or compute the generated random word and are excluded as sequencing or working values."
    },
    {
      "Candidate Name": "Clock and reset",
      "Candidate Unit": "neorv32_trng",
      "Merged Into": "",
      "Why Not Kept": "clk_i and rstn_i only time or reset the generator, FIFO, and bus response, so the clocks-and-resets rule excludes them as conceptual assets."
    },
    {
      "Candidate Name": "FIFO-size and simulation-mode configuration",
      "Candidate Unit": "neorv32_trng",
      "Merged Into": "",
      "Why Not Kept": "TRNG_FIFO, SIM_MODE, the FIFO size readback, and the simulation-mode readback are build-time values that no element can change or withhold at run time."
    },
    {
      "Candidate Name": "Bus acknowledge and constant error status",
      "Candidate Unit": "neorv32_trng",
      "Merged Into": "",
      "Why Not Kept": "bus_rsp_o.ack only repeats the request strobe and bus_rsp_o.err is tied to a constant, so bus-handshake copies do not form separate information."
    }
  ],
  "Notes": []
}
